import"./chunk-4CLCTAJ7.js";var t="Paid advertising either prints money or burns it. The difference is almost never the budget \u2014 it's the strategy behind it.",n=["Businesses running Google Ads without proper conversion tracking. Meta campaigns targeting audiences that haven't been tested. Landing pages that don't match the ad copy. Budgets spread across platforms that don't actually perform.","At Bhiive, we manage paid marketing campaigns for B2B businesses, service brands and e-commerce companies that want predictable lead generation and measurable returns \u2014 not vanity metrics."],i=["Optimised for cost per qualified lead and ROAS","Conversion tracking verified before we scale","Google Ads leads often within the first week"],o=[{type:"text",id:"the-problem",heading:"The problem with most paid marketing agencies",paragraphs:["Most agencies optimise for metrics that look impressive in reports but don't grow your business. High click-through rates don't matter if the leads don't convert. Low CPCs don't matter if the traffic is unqualified.","We optimise for what actually matters: cost per qualified lead, conversion rate, customer acquisition cost and return on ad spend (ROAS)."]},{type:"text",id:"whats-changed",heading:"Paid marketing in 2026: what's changed",paragraphs:["Google's AI-powered Smart Bidding and Meta's machine-learning systems now reward advertisers who provide strong conversion data, high-quality creative and optimised landing pages.","Today, creative quality, accurate tracking, landing page optimisation and first-party data matter more than manual targeting hacks."]},{type:"cards",id:"services",heading:"Our paid marketing services",items:[{title:"Google Ads management",text:"Google Ads campaigns designed for lead generation, sales and measurable business growth.",points:["Search, Display & Performance Max campaigns","Keyword & competitor research","Ad copywriting & optimisation","Conversion tracking setup","Bidding strategy management","Monthly performance reporting"]},{title:"Meta Ads management",text:"Facebook and Instagram campaigns focused on audience growth, lead generation and sales.",points:["Audience research & segmentation","Creative strategy & ad concepts","Retargeting campaign setup","Pixel & Conversions API integration","Ad testing & optimisation","Full-funnel campaign management"]},{title:"LinkedIn Ads",text:"Reach decision-makers and B2B audiences with highly targeted LinkedIn campaigns.",points:["Sponsored Content campaigns","Lead Gen Forms setup","Targeting by industry & role","Conversation & Message Ads","A/B testing","B2B lead generation optimisation"]},{title:"Landing page & conversion optimisation",text:"Landing pages that improve conversion rates, reduce bounce and get more from every rupee of ad spend.",points:["Campaign landing page design","Headline & CTA optimisation","Form optimisation","Mobile speed improvements","Heatmap & behaviour analysis","Conversion-focused UX improvements"]},{title:"Paid ads audit",text:"An audit of your existing campaigns to find wasted spend, tracking gaps and performance bottlenecks.",points:["Campaign structure review","Keyword & audience analysis","Tracking verification","Creative performance assessment","Landing page evaluation","Actionable optimisation roadmap"]}]},{type:"checklist",id:"what-to-expect",heading:"What you can expect",items:["Transparent reporting focused on leads and ROAS","Weekly campaign optimisation and testing","Accurate conversion tracking and attribution","Creative and landing pages aligned for higher conversions","Continuous improvement based on real campaign data"]},{type:"steps",id:"approach",heading:"Our strategic approach",items:[{title:"Campaign strategy & research",text:"We understand your goals, audience, competitors and current performance before launching anything."},{title:"Creative & landing page alignment",text:"Ad copy and landing page experiences written to match, so conversion rates go up."},{title:"Tracking & optimisation",text:"Advanced tracking in place, then continuous optimisation based on performance data."},{title:"Reporting & scaling",text:"Transparent reporting, and more budget only behind campaigns that are consistently profitable."}]}],s=[{q:"What's the minimum budget for Google or Meta Ads?",a:"We typically recommend \u20B930,000\u2013\u20B950,000 per month for Google Ads and \u20B920,000 per month for Meta Ads to gather enough optimisation data."},{q:"How long before paid campaigns generate results?",a:"Google Ads can generate leads within the first week, while Meta campaigns often need 2\u20134 weeks of testing and optimisation."},{q:"Do you create ad creatives and copy?",a:"Yes. We handle ad copywriting, campaign messaging and creative strategy for paid campaigns."},{q:"Can you manage existing campaigns?",a:"Absolutely. We audit and optimise existing Google Ads, Meta Ads and LinkedIn campaigns for better performance."},{q:"Do you guarantee results?",a:"We don't guarantee specific lead numbers, but we do guarantee transparent management, ongoing optimisation and honest reporting."}],r=["digital-marketing","web-development","marketing-automation"],d={heading:"Find out where your ad budget is leaking",text:"Send us access to your ad accounts and we'll show you the wasted spend, tracking gaps and quick wins \u2014 before you commit to anything."},g={lead:t,intro:n,highlights:i,sections:o,faqs:s,related:r,cta:d};export{d as cta,g as default,s as faqs,i as highlights,n as intro,t as lead,r as related,o as sections};
